update_rule.pseudocode:
if day == supply_shock_day: for each retailer r: for each type t: r.restock_quantity_by_type[t] *= supply_shock_multiplier
for each retailer r:
  if day % restock_interval_days == 0:
    for each type t: r.inventory_by_type[t] += r.restock_quantity_by_type[t]
  # price adjustment if low inventory
  for each type t:
    inv_ratio = r.inventory_by_type[t] / (1 + r.restock_quantity_by_type[t])
    if inv_ratio < 0.5: r.price_by_type[t] *= (1 + stockout_price_markup * (0.5 - inv_ratio))
    else: r.price_by_type[t] *= (1 - price_adjustment_sensitivity * 0.1)
# purchase phase
for each person i in random_order:
  demand = i.decide_to_purchase_masks()
  for (t, qty) in demand.items():
    allowed_qty = min(qty, purchase_limit_per_visit) if rationing_policy else qty
    for retailer r in retailers_shuffled:
      buy = min(allowed_qty, r.inventory_by_type[t])
      total_cost = buy * r.price_by_type[t]
      if buy > 0 and total_cost <= i.income * affordability_sensitivity:
        r.inventory_by_type[t] -= buy
        i.masks_on_hand += buy
        record transaction
        allowed_qty -= buy
      if allowed_qty <= 0: break
# stockout flags
for each retailer r: for t: stockout_flags_by_type[r.id,t] = (r.inventory_by_type[t] == 0)

capacity = min(Authority.enforcement_capacity_per_day, total_noncompliant_in_mandated_contexts)
select persons in mandated contexts with adoption_state==0 weighted by location.enforcement_level up to capacity
for each selected person i:
  if rand() < enforcement_warning_probability:
    record warning
    i.perceived_cost = clamp(i.perceived_cost + 0.05, 0, 1)
  else if rand() < mandate_enforcement_probability:
    record fine
    i.perceived_cost = clamp(i.perceived_cost + adoption_sensitivity_to_fine * fine_amount / 100.0, 0, 1)
    i.adoption_state = 1 if rand() < 0.5 else i.adoption_state

for each person i:
  draw context_time_share ~ Dirichlet proportional to location_mix (adjusted by routine_profile)
  for each context c with policy=='required' and i.adoption_state==0:
    if rand() < denial_of_entry_probability:
      denied_entries_daily += 1
      reduce time_share[c] and reassign to 'home'

if day == mandate_start_day:
  for each location with type in policy_mask_required_location_types:
    location.mask_policy = 'required'
  Authority.policy_state = 'mandate_active'
